def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    from functools import wraps
    from collections import OrderedDict
    import time

    def decorator(func):
        cache = OrderedDict()
        stats = [0, 0]  # Hit, Miss

        def wrapper(*args, **kwargs):
            if typed:
                key = (args, tuple(sorted(kwargs.items())))
            else:
                key = args + tuple(kwargs.items())

            # Check if the key is in the cache and not expired
            now = timer()
            if key in cache:
                result, expiry = cache[key]
                if expiry > now:
                    cache.move_to_end(key)  # Mark as recently used
                    stats[0] += 1
                    return result
                else:
                    del cache[key]  # Expired, remove from cache

            # Call the function and cache the result with a TTL
            result = func(*args, **kwargs)
            cache[key] = (result, now + ttl)
            cache.move_to_end(key)  # Mark as recently used
            if maxsize and len(cache) > maxsize:
                cache.popitem(last=False)  # Pop the oldest entry
            stats[1] += 1
            return result

        def cache_info():
            return (stats[0], stats[1], maxsize, len(cache))

        def cache_clear():
            cache.clear()
            stats[0] = stats[1] = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wraps(func)(wrapper)

    return decorator

