def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    minimal = []
    for cls in classes:
        if cls not in seen:
            minimal.append(cls)
            seen.add(cls)
            for base in cls.__bases__:
                if base in seen:
                    seen.remove(base)
    return minimal

