def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    def is_fill_request(element):
        return isinstance(element, FillRequest) and not isinstance(element, Source)

    if is_fill_request(seq):
        return True
    if not isinstance(seq, (list, tuple)):
        return False
    return any(is_fill_request(item) for item in seq) and not any(isinstance(item, Source) for item in seq)

