def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    required_digests = set()
    for file_data in manifest_files:
        required_digests.add(file_data['digest'])

    for digest in required_digests:
        if digest not in digests_used:
            raise ValueError(f"Digest {digest} is required but not used.")
    for digest in digests_used:
        if digest not in required_digests:
            raise ValueError(f"Digest {digest} is used but not present in the manifest.")

