def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    metaclasses = set()

    # Collect all metaclasses from bases
    for base in bases:
        if isinstance(base, type):
            metaclasses.add(base.__class__)

    # If an explicit metaclass is given, use it
    if explicit_mc is not None:
        metaclasses.add(explicit_mc)

    # If no metaclasses were found, use type as default
    if not metaclasses:
        return type

    # Find the most derived metaclass
    mcs = list(metaclasses)
    metaclasstypes = {}
    while mcs:
        metacls = mcs.pop()
        metaclasstypes[metacls] = metacls.mro()
        mcs.extend([c for c in metacls.__bases__ if c not in metaclasses])

    candidate = None
    for metacls, mro in metaclasstypes.items():
        if all(issubclass(c, metacls) for c in metaclasstypes):
            if candidate is None or metaclasstypes[metacls] > metaclasstypes[candidate]:
                candidate = metacls

    if candidate is None:
        raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of all its bases")

    return candidate

